export function initShortcutRouter(o,f){window.addEventListener("keydown",t=>{let c=t.key.toLowerCase();if(["control","meta","shift","alt"].includes(c))return;let e="";(t.ctrlKey||t.metaKey)&&(e+="ctrl+"),t.shiftKey&&(e+="shift+"),t.altKey&&(e+="alt+");const r=e+(c===" "?"space":c),l=f?f():["global"];if(!(!o||!o.shortcuts)){for(let n of l)if(o.shortcuts[n]&&o.shortcuts[n][r]){t.preventDefault(),o.shortcuts[n][r](t);return}}})}
